<?php
declare(strict_types=1);
/** ShahkotPK v12.0.0 — Customer Super App + Personal AI Concierge. */
if(!function_exists('sk1200_h')){
function sk1200_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sk1200_tid():int{try{if(function_exists('tenant_id'))return (int)tenant_id();if(function_exists('current_tenant')){$t=current_tenant();return (int)($t['id']??0);}}catch(Throwable $e){}return 0;}
function sk1200_user():array{try{$u=function_exists('current_user')?current_user():null;return is_array($u)?$u:[];}catch(Throwable $e){return [];}}
function sk1200_uid():int{return (int)(sk1200_user()['id']??0);}
function sk1200_table(string $t):bool{static $c=[];if(isset($c[$t]))return $c[$t];if(!preg_match('/^[A-Za-z][A-Za-z0-9_]{0,63}$/',$t))return false;try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1');$q->execute([$t]);return $c[$t]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$t]=false;}}
function sk1200_cols(string $t):array{static $c=[];if(isset($c[$t]))return $c[$t];if(!sk1200_table($t))return $c[$t]=[];try{$q=db()->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$q->execute([$t]);return $c[$t]=$q->fetchAll(PDO::FETCH_COLUMN)?:[];}catch(Throwable $e){return $c[$t]=[];}}
function sk1200_visitor_key():string{if(!empty($_COOKIE['sk_visitor_key'])&&preg_match('/^[a-f0-9]{32,64}$/',(string)$_COOKIE['sk_visitor_key']))return (string)$_COOKIE['sk_visitor_key'];$k=hash('sha256',session_id().'|'.($_SERVER['REMOTE_ADDR']??'').'|'.($_SERVER['HTTP_USER_AGENT']??''));if(!headers_sent())setcookie('sk_visitor_key',$k,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);return $k;}
function sk1200_settings():array{$d=['enabled'=>1,'ai_enabled'=>1,'guest_mode'=>1,'do_it_for_me'=>1,'max_business_matches'=>5,'show_unified_inbox'=>1,'show_wallet'=>1,'show_recent'=>1,'show_bookings'=>1,'offer_expiry_hours'=>72,'privacy_days'=>180];if(!sk1200_table('customer_superapp_settings_v1200'))return $d;try{$q=db()->prepare('SELECT * FROM customer_superapp_settings_v1200 WHERE tenant_id=? LIMIT 1');$q->execute([sk1200_tid()]);return array_merge($d,$q->fetch()?:[]);}catch(Throwable $e){return $d;}}
function sk1200_save_settings(array $in):void{$tid=sk1200_tid();$v=[!empty($in['enabled'])?1:0,!empty($in['ai_enabled'])?1:0,!empty($in['guest_mode'])?1:0,!empty($in['do_it_for_me'])?1:0,max(1,min(10,(int)($in['max_business_matches']??5))),!empty($in['show_unified_inbox'])?1:0,!empty($in['show_wallet'])?1:0,!empty($in['show_recent'])?1:0,!empty($in['show_bookings'])?1:0,max(1,min(336,(int)($in['offer_expiry_hours']??72))),max(30,min(730,(int)($in['privacy_days']??180)))];db()->prepare('INSERT INTO customer_superapp_settings_v1200(tenant_id,enabled,ai_enabled,guest_mode,do_it_for_me,max_business_matches,show_unified_inbox,show_wallet,show_recent,show_bookings,offer_expiry_hours,privacy_days,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),ai_enabled=VALUES(ai_enabled),guest_mode=VALUES(guest_mode),do_it_for_me=VALUES(do_it_for_me),max_business_matches=VALUES(max_business_matches),show_unified_inbox=VALUES(show_unified_inbox),show_wallet=VALUES(show_wallet),show_recent=VALUES(show_recent),show_bookings=VALUES(show_bookings),offer_expiry_hours=VALUES(offer_expiry_hours),privacy_days=VALUES(privacy_days),updated_at=NOW()')->execute(array_merge([$tid],$v));}
function sk1200_scope_sql(string $alias=''):array{$p=$alias!==''?$alias.'.':'';$uid=sk1200_uid();if($uid>0)return [$p.'user_id=?',[$uid]];return [$p.'visitor_key=?',[sk1200_visitor_key()]];}
function sk1200_summary():array{$tid=sk1200_tid();$uid=sk1200_uid();$vk=sk1200_visitor_key();$o=['bookings'=>0,'favorites'=>0,'points'=>0,'requests'=>0,'offers'=>0,'messages'=>0,'notifications'=>0,'saved_deals'=>0];try{if(sk1200_table('unified_bookings_v1040')){$q=db()->prepare('SELECT COUNT(*) FROM unified_bookings_v1040 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'visitor_hash=?'));$q->execute([$tid,$uid>0?$uid:hash('sha256',$vk)]);$o['bookings']=(int)$q->fetchColumn();}if(sk1200_table('visitor_favorites_v1020')){$q=db()->prepare('SELECT COUNT(*) FROM visitor_favorites_v1020 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'visitor_key=?'));$q->execute([$tid,$uid>0?$uid:$vk]);$o['favorites']=(int)$q->fetchColumn();}if($uid>0&&sk1200_table('local_loyalty_accounts_v1050')){$q=db()->prepare('SELECT points_balance FROM local_loyalty_accounts_v1050 WHERE tenant_id=? AND user_id=?');$q->execute([$tid,$uid]);$o['points']=(int)($q->fetchColumn()?:0);}if(sk1200_table('customer_intents_v1200')){[$w,$p]=sk1200_scope_sql();$q=db()->prepare('SELECT COUNT(*) FROM customer_intents_v1200 WHERE tenant_id=? AND '.$w." AND status IN ('open','matched','offers_received')");$q->execute(array_merge([$tid],$p));$o['requests']=(int)$q->fetchColumn();}if(sk1200_table('customer_intent_matches_v1200')&&sk1200_table('customer_intents_v1200')){[$w,$p]=sk1200_scope_sql('i');$q=db()->prepare("SELECT COUNT(*) FROM customer_intent_matches_v1200 m JOIN customer_intents_v1200 i ON i.id=m.intent_id WHERE i.tenant_id=? AND $w AND m.status='offered'");$q->execute(array_merge([$tid],$p));$o['offers']=(int)$q->fetchColumn();}if($uid>0&&sk1200_table('business_crm_contacts_v1180')&&sk1200_table('business_crm_conversations_v1180')){$q=db()->prepare("SELECT COUNT(*) FROM business_crm_conversations_v1180 c JOIN business_crm_contacts_v1180 x ON x.id=c.contact_id WHERE c.tenant_id=? AND x.user_id=? AND c.status='open'");$q->execute([$tid,$uid]);$o['messages']=(int)$q->fetchColumn();}if(sk1200_table('growth_notifications_v1020')){$q=db()->prepare('SELECT COUNT(*) FROM growth_notifications_v1020 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'visitor_key=?'));$q->execute([$tid,$uid>0?$uid:$vk]);$o['notifications']=(int)$q->fetchColumn();}if($uid>0&&sk1200_table('local_deal_claims_v1050')){$q=db()->prepare("SELECT COUNT(*) FROM local_deal_claims_v1050 WHERE tenant_id=? AND user_id=? AND status='saved'");$q->execute([$tid,$uid]);$o['saved_deals']=(int)$q->fetchColumn();}}catch(Throwable $e){}return $o;}
function sk1200_recent_bookings(int $limit=5):array{if(!sk1200_table('unified_bookings_v1040'))return [];$tid=sk1200_tid();$uid=sk1200_uid();try{$q=db()->prepare('SELECT * FROM unified_bookings_v1040 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'visitor_hash=?').' ORDER BY id DESC LIMIT '.max(1,min(20,$limit)));$q->execute([$tid,$uid>0?$uid:hash('sha256',sk1200_visitor_key())]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1200_recent_notifications(int $limit=6):array{if(!sk1200_table('growth_notifications_v1020'))return [];$tid=sk1200_tid();$uid=sk1200_uid();try{$q=db()->prepare('SELECT * FROM growth_notifications_v1020 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'visitor_key=?').' ORDER BY id DESC LIMIT '.max(1,min(20,$limit)));$q->execute([$tid,$uid>0?$uid:sk1200_visitor_key()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1200_recent_deals(int $limit=5):array{if(sk1200_uid()<1||!sk1200_table('local_deal_claims_v1050')||!sk1200_table('local_deals_v1050'))return [];$q=db()->prepare('SELECT c.*,d.title,d.ends_at,d.business_id FROM local_deal_claims_v1050 c JOIN local_deals_v1050 d ON d.id=c.deal_id WHERE c.tenant_id=? AND c.user_id=? ORDER BY c.id DESC LIMIT '.max(1,min(20,$limit)));$q->execute([sk1200_tid(),sk1200_uid()]);return $q->fetchAll()?:[];}
function sk1200_recent_crm(int $limit=5):array{if(sk1200_uid()<1||!sk1200_table('business_crm_contacts_v1180')||!sk1200_table('business_crm_conversations_v1180'))return [];try{$q=db()->prepare('SELECT c.*,x.customer_name,b.name business_name FROM business_crm_conversations_v1180 c JOIN business_crm_contacts_v1180 x ON x.id=c.contact_id LEFT JOIN businesses b ON b.id=c.business_id WHERE c.tenant_id=? AND x.user_id=? ORDER BY c.last_message_at DESC,c.id DESC LIMIT '.max(1,min(20,$limit)));$q->execute([sk1200_tid(),sk1200_uid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1200_intents(int $limit=20):array{if(!sk1200_table('customer_intents_v1200'))return [];$tid=sk1200_tid();[$w,$p]=sk1200_scope_sql();try{$q=db()->prepare('SELECT * FROM customer_intents_v1200 WHERE tenant_id=? AND '.$w.' ORDER BY id DESC LIMIT '.max(1,min(100,$limit)));$q->execute(array_merge([$tid],$p));$rows=$q->fetchAll()?:[];foreach($rows as &$r){$r['matches']=sk1200_intent_matches((int)$r['id']);}return $rows;}catch(Throwable $e){return [];}}
function sk1200_intent_matches(int $intentId):array{if(!sk1200_table('customer_intent_matches_v1200'))return [];try{$q=db()->prepare('SELECT m.*,b.name business_name,b.phone business_phone,b.whatsapp business_whatsapp FROM customer_intent_matches_v1200 m LEFT JOIN businesses b ON b.id=m.business_id WHERE m.intent_id=? ORDER BY (m.status=\'offered\') DESC,m.match_score DESC,m.id ASC');$q->execute([$intentId]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1200_tokens(string $text):array{$x=mb_strtolower(strip_tags($text));$all=preg_split('/[^\pL\pN]+/u',$x)?:[];$stop=['the','and','for','with','need','want','mujhe','chahiye','ka','ki','ke','main','me','aur','aik','one','today','shahkot'];return array_values(array_unique(array_filter($all,fn($v)=>mb_strlen($v)>=3&&!in_array($v,$stop,true))));}
function sk1200_business_candidates(string $need,string $area='',int $limit=5):array{if(!sk1200_table('businesses'))return [];$cols=sk1200_cols('businesses');$sel=['b.id'];foreach(['name','description','tagline','address','area','phone','whatsapp','owner_id','owner_user_id','category_id','status','image','image_url'] as $c)if(in_array($c,$cols,true))$sel[]='b.`'.$c.'`';$join='';if(sk1200_table('categories')&&in_array('category_id',$cols,true)){$join=' LEFT JOIN categories c ON c.id=b.category_id ';$sel[]='c.name category_name';}$where=[];$p=[];if(in_array('tenant_id',$cols,true)&&sk1200_tid()>0){$where[]='b.tenant_id=?';$p[]=sk1200_tid();}if(in_array('status',$cols,true))$where[]="LOWER(CAST(b.status AS CHAR)) NOT IN ('deleted','inactive','rejected','disabled','0')";$sql='SELECT '.implode(',',$sel).' FROM businesses b '.$join.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY b.id DESC LIMIT 300';try{$q=db()->prepare($sql);$q->execute($p);$rows=$q->fetchAll()?:[];}catch(Throwable $e){return [];}$tokens=sk1200_tokens($need.' '.$area);$scored=[];foreach($rows as $r){$hay=mb_strtolower(implode(' ',array_map(fn($x)=>is_scalar($x)?(string)$x:'',$r)));$score=0;foreach($tokens as $t){if(str_contains($hay,$t))$score+=str_contains(mb_strtolower((string)($r['name']??'')),$t)?8:3;}if($area!==''&&str_contains($hay,mb_strtolower($area)))$score+=5;if($score<=0&&$tokens)$score=1;$r['_score']=$score;$scored[]=$r;}usort($scored,fn($a,$b)=>$b['_score']<=>$a['_score']);return array_slice($scored,0,max(1,min(10,$limit)));}
function sk1200_create_intent(array $d):array{$s=sk1200_settings();if(empty($s['enabled'])||empty($s['do_it_for_me']))throw new RuntimeException('Do It For Me is currently disabled.');$uid=sk1200_uid();if($uid<1&&empty($s['guest_mode']))throw new RuntimeException('Please sign in first.');$need=mb_substr(trim((string)($d['need_text']??'')),0,1200);if(mb_strlen($need)<5)throw new InvalidArgumentException('Tell us what you need.');$name=mb_substr(trim((string)($d['contact_name']??(sk1200_user()['name']??''))),0,120);$phone=mb_substr(trim((string)($d['contact_phone']??(sk1200_user()['phone']??''))),0,60);if($name===''||$phone==='')throw new InvalidArgumentException('Name and phone are required so businesses can respond.');$area=mb_substr(trim((string)($d['area']??'')),0,160);$cat=mb_substr(preg_replace('/[^a-z0-9_-]/','',mb_strtolower((string)($d['category_key']??'general'))),0,60)?:'general';$urg=in_array(($d['urgency']??'normal'),['normal','today','urgent','this_week'],true)?$d['urgency']:'normal';$bmin=max(0,(float)($d['budget_min']??0));$bmax=max(0,(float)($d['budget_max']??0));$token=bin2hex(random_bytes(24));$q=db()->prepare("INSERT INTO customer_intents_v1200(tenant_id,user_id,visitor_key,public_token,category_key,need_text,budget_min,budget_max,area,urgency,contact_name,contact_phone,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'open',NOW(),NOW())");$q->execute([sk1200_tid(),$uid?:null,sk1200_visitor_key(),$token,$cat,$need,$bmin,$bmax,$area,$urg,$name,$phone]);$id=(int)db()->lastInsertId();$matches=sk1200_business_candidates($need,$area,(int)$s['max_business_matches']);foreach($matches as $r){db()->prepare("INSERT IGNORE INTO customer_intent_matches_v1200(tenant_id,intent_id,business_id,match_score,status,created_at,updated_at) VALUES(?,?,?,?, 'matched',NOW(),NOW())")->execute([sk1200_tid(),$id,(int)$r['id'],(int)$r['_score']]);}if($matches)db()->prepare("UPDATE customer_intents_v1200 SET status='matched',matched_count=?,updated_at=NOW() WHERE id=?")->execute([count($matches),$id]);return ['id'=>$id,'token'=>$token,'matches'=>count($matches)];}
function sk1200_business_ids_for_user(int $uid):array{if($uid<1||!sk1200_table('businesses'))return [];$cols=sk1200_cols('businesses');$parts=[];$p=[];foreach(['owner_user_id','owner_id'] as $c)if(in_array($c,$cols,true)){$parts[]="`$c`=?";$p[]=$uid;}if(!$parts)return [];try{$q=db()->prepare('SELECT id FROM businesses WHERE '.implode(' OR ',$parts));$q->execute($p);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)?:[]);}catch(Throwable $e){return [];}}
function sk1200_opportunities(int $uid):array{$ids=sk1200_business_ids_for_user($uid);if(!$ids||!sk1200_table('customer_intent_matches_v1200'))return [];$ph=implode(',',array_fill(0,count($ids),'?'));try{$q=db()->prepare("SELECT m.*,i.need_text,i.area,i.urgency,i.budget_min,i.budget_max,i.created_at request_created,b.name business_name FROM customer_intent_matches_v1200 m JOIN customer_intents_v1200 i ON i.id=m.intent_id JOIN businesses b ON b.id=m.business_id WHERE m.tenant_id=? AND m.business_id IN ($ph) AND i.status NOT IN ('closed','cancelled') ORDER BY (m.status='offered') ASC,i.id DESC LIMIT 200");$q->execute(array_merge([sk1200_tid()],$ids));return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1200_submit_offer(int $matchId,int $uid,array $d):void{$ids=sk1200_business_ids_for_user($uid);if(!$ids)throw new RuntimeException('No business is attached to your account.');$ph=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT m.* FROM customer_intent_matches_v1200 m WHERE m.id=? AND m.business_id IN ($ph) LIMIT 1");$q->execute(array_merge([$matchId],$ids));$m=$q->fetch();if(!$m)throw new RuntimeException('Opportunity not found.');$price=max(0,(float)($d['offer_price']??0));$msg=mb_substr(trim((string)($d['offer_message']??'')),0,1500);if($msg===''&&$price<=0)throw new InvalidArgumentException('Add a price or message.');db()->prepare("UPDATE customer_intent_matches_v1200 SET status='offered',offer_price=?,offer_message=?,offered_by=?,responded_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$price,$msg,$uid,$matchId]);db()->prepare("UPDATE customer_intents_v1200 i SET status='offers_received',updated_at=NOW() WHERE id=?")->execute([(int)$m['intent_id']]);}
function sk1200_my_answer(string $message):array{$m=mb_strtolower(trim($message));$s=sk1200_summary();try{$cf=__DIR__.'/commerce_v1230.php';if(is_file($cf))require_once $cf;if(function_exists('sk1230_customer_stats')){$co=sk1230_customer_stats();if(preg_match('/cart|basket|onecart/',$m))return ['answer'=>'Your ShahkotPK OneCart currently has '.$co['cart'].' item(s).','url'=>'/cart-v1230.php','mode'=>'personal'];if(preg_match('/order|delivery|parcel|track/',$m))return ['answer'=>'You have '.$co['orders'].' commerce order(s), including '.$co['active'].' active order(s) or deliveries.','url'=>'/my-orders-v1230.php','mode'=>'personal'];if(preg_match('/membership|plus|member/',$m))return ['answer'=>$co['member']!==''?'Your active membership is '.$co['member'].'.':'You are currently on the standard customer experience. You can view available ShahkotPK Plus plans.','url'=>'/membership-v1230.php','mode'=>'personal'];if(preg_match('/cashback|commerce wallet|order wallet/',$m))return ['answer'=>'Your commerce wallet balance is '.sk1230_money($co['wallet']).'.','url'=>'/membership-v1230.php','mode'=>'personal'];}}catch(Throwable $e){}if(preg_match('/book|appointment|booking/',$m))return ['answer'=>'You currently have '.$s['bookings'].' booking(s). Open My Bookings to see dates and statuses.','url'=>'/my-bookings-v1040.php','mode'=>'personal'];if(preg_match('/point|reward|wallet/',$m))return ['answer'=>'Your current ShahkotPK rewards balance is '.$s['points'].' points, with '.$s['saved_deals'].' saved deal(s).','url'=>'/my-wallet-v1050.php','mode'=>'personal'];if(preg_match('/offer|quote|quotation/',$m))return ['answer'=>'You have '.$s['offers'].' offer(s) on your active concierge requests and '.$s['messages'].' open business conversation(s).','url'=>'/my-shahkot.php#requests','mode'=>'personal'];if(preg_match('/request|need|service/',$m))return ['answer'=>'You currently have '.$s['requests'].' active “Do It For Me” request(s). You can create a new request below and ShahkotPK will match relevant businesses.','url'=>'/my-shahkot.php#need-it','mode'=>'personal'];if(preg_match('/favorite|saved/',$m))return ['answer'=>'You have '.$s['favorites'].' saved favorite(s).','url'=>'/favorites-v1020.php','mode'=>'personal'];if(!empty(sk1200_settings()['ai_enabled'])){try{$f=__DIR__.'/ai_copilot_v1100.php';if(is_file($f))require_once $f;if(function_exists('sk1100ai_chat')){$r=sk1100ai_chat($message,'public');return ['answer'=>(string)$r['answer'],'url'=>'','mode'=>(string)($r['mode']??'ai'),'sources'=>$r['sources']??[]];}}catch(Throwable $e){}}return ['answer'=>'I can help with bookings, deals, favorites, business offers, service requests and ShahkotPK discovery. Try “show my bookings” or tell me what you need today.','url'=>'','mode'=>'local'];}
function sk1200_admin_stats():array{$o=['users'=>0,'intents'=>0,'offers'=>0,'open'=>0];try{if(sk1200_table('customer_intents_v1200')){$q=db()->prepare('SELECT COUNT(*),SUM(status IN (\'open\',\'matched\',\'offers_received\')) FROM customer_intents_v1200 WHERE tenant_id=?');$q->execute([sk1200_tid()]);$r=$q->fetch(PDO::FETCH_NUM);$o['intents']=(int)($r[0]??0);$o['open']=(int)($r[1]??0);$q=db()->prepare('SELECT COUNT(DISTINCT COALESCE(user_id,0)) FROM customer_intents_v1200 WHERE tenant_id=? AND user_id IS NOT NULL');$q->execute([sk1200_tid()]);$o['users']=(int)$q->fetchColumn();}if(sk1200_table('customer_intent_matches_v1200')){$q=db()->prepare("SELECT COUNT(*) FROM customer_intent_matches_v1200 WHERE tenant_id=? AND status='offered'");$q->execute([sk1200_tid()]);$o['offers']=(int)$q->fetchColumn();}}catch(Throwable $e){}return $o;}
}
